 src=H/'sources/registered_port_approach_r01_fine_r02.json';m=read(src);audit=read(H/'native_overlap_audit.json');pack=read(H/'resolved_placements.json');oldasset=pack['assets'][1];native=read(ROOT/oldasset['cache']['path']);qs=sorted(set(r['new_quad']for r in audit['overlaps']if abs(r['new_y']-r['old_y'])<1e-9));assert len(qs)==2;m['id']='registered_port_approach_r01_fine_r03';m['revision']=3;m['assembly_cuts']=[];cuts=[]
 for qi in qs:
  q=native['groups'][0]['quads'][qi];arr=np.asarray(q);mn=arr.min(0);mx=arr.max(0);assert mn[1]==mx[1]==2.2;lo=[float(mn[0]),2.15,float(mn[2])];hi=[float(mx[0]),2.25,float(mx[2])];m['assembly_cuts'].append(dict(id='new_cap_quay_coplanar_recess_'+str(qi),selector={},action='cut',shape=box(lo,hi)));cuts.append(dict(quad=qi,bounds_min=lo,bounds_max=hi))
 m['provenance']['coplanar_recess']=dict(source=ref(src),prior_overlap=ref(H/'native_overlap_audit.json'),implementation=ref(H/'recess_quay_contact_r03.py'),cuts=cuts,scope='Two new cap strips only, recessed by one 5 cm visible sampling layer below the retained +2.2 quay. No retained native asset, walking profile, or active coarse collider changes.')
 mp=H/'sources'/(m['id']+'.json');write(mp,m);start=time.monotonic();co=coordinate_planes.compile_master(m,dict(pitch=.05),max_candidate_cells=4000000,max_output_cells=1000000);assert co['valid'];ren=render_data.make_render_data(co);cp=H/'cache'/(m['id']+'.compiled.json');rp=H/'cache'/(m['id']+'.render.json');write(cp,co);write(rp,ren);newasset=dict(id=m['id'],source=ref(mp),compiled=ref(cp),cache=ref(rp),pitch_m=.05,output_cells=len(co['cells']),candidate_cells=co['candidate_cells'],bounds=ren['bounds'],quad_count=ren['quad_count'],seconds=time.monotonic()-start)
 pack['assets'][1]=newasset;pack['placements'][1]['asset_key']=m['id'];pack['source_refs'].append(ref(mp));write(H/'resolved_placements_r02.json',pack);c=read(H/'collision_contract.json');c['native_pack']=ref(H/'resolved_placements_r02.json');write(H/'collision_contract_r02.json',c);write(H/'quay_contact_recess_ledger.json',dict(old_asset=oldasset,new_asset=newasset,source_cuts=cuts,previous_coplanar_area_m2=audit['coplanar_overlap_m2'],walking_contract_vertices_unchanged=c['add_triangles_world_xyz_m']==read(H/'collision_contract.json')['add_triangles_world_xyz_m'],active_support_unchanged=pack['assets'][0]==read(H/'resolved_placements.json')['assets'][0]));print(json.dumps(newasset),flush=True)
